import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Tooling and SDK generation","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/tooling.md","filePath":"ecosystem/tooling.md"}`),a={name:`ecosystem/tooling.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="tooling-and-sdk-generation" tabindex="-1">Tooling and SDK generation <a class="header-anchor" href="#tooling-and-sdk-generation" aria-label="Permalink to “Tooling and SDK generation”">​</a></h1><p>Beyond the language-operation engines, the <code>tool-*</code> family includes the <strong>codegen pipeline</strong>: the machinery that turns foreign interfaces — C headers, WebIDL specs, OpenAPI documents, command-line tools — into typed Handl surfaces. This is the edge of the ecosystem: generated, not hand-written, bindings are how Handl talks to the outside world.</p><h2 id="the-codegen-kernel" tabindex="-1">The codegen kernel <a class="header-anchor" href="#the-codegen-kernel" aria-label="Permalink to “The codegen kernel”">​</a></h2><ul><li><a href="https://github.com/handl-lang/tool-codegen" target="_blank" rel="noreferrer">tool-codegen</a> — <code>hnl-tool-codegen</code>, the desired-state codegen kernel. The pipeline is <code>Lift → Transform → Emit</code>: lift a foreign spec into an intermediate representation, transform it, emit typed Handl modules.</li></ul><h2 id="backends-spec-→-ir" tabindex="-1">Backends (spec → IR) <a class="header-anchor" href="#backends-spec-→-ir" aria-label="Permalink to “Backends (spec → IR)”">​</a></h2><p>Each backend parses one foreign spec language:</p><table tabindex="0"><thead><tr><th>Repo</th><th>Spec it lifts</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/tool-codegen-c" target="_blank" rel="noreferrer">tool-codegen-c</a></td><td>C headers via libclang</td></tr><tr><td><a href="https://github.com/handl-lang/tool-codegen-webidl" target="_blank" rel="noreferrer">tool-codegen-webidl</a></td><td>WebIDL — browser/worker APIs</td></tr><tr><td><a href="https://github.com/handl-lang/tool-codegen-openapi" target="_blank" rel="noreferrer">tool-codegen-openapi</a></td><td>OpenAPI documents</td></tr><tr><td><a href="https://github.com/handl-lang/tool-codegen-cli" target="_blank" rel="noreferrer">tool-codegen-cli</a></td><td>CLI tools — <code>*.clispec.yaml</code> specs or live <code>--help</code> probes</td></tr></tbody></table><h2 id="emitters-ir-→-handl" tabindex="-1">Emitters (IR → Handl) <a class="header-anchor" href="#emitters-ir-→-handl" aria-label="Permalink to “Emitters (IR → Handl)”">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>What it emits</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/tool-codegen-file" target="_blank" rel="noreferrer">tool-codegen-file</a></td><td><code>.hnl</code> module files (<code>hnl-file</code> emitter)</td></tr><tr><td><a href="https://github.com/handl-lang/tool-codegen-python" target="_blank" rel="noreferrer">tool-codegen-python</a></td><td>Python <code>ctypes</code> SDKs for C headers</td></tr></tbody></table><p>Generated output lands as <code>handl-packages/generated/</code> bindings inside the consuming repo; multi-consumer bindings graduate to their own <code>lib-*</code> repos — <a href="https://github.com/handl-lang/lib-libc" target="_blank" rel="noreferrer">lib-libc</a>, <a href="https://github.com/handl-lang/lib-curl" target="_blank" rel="noreferrer">lib-curl</a>, <a href="https://github.com/handl-lang/lib-libz" target="_blank" rel="noreferrer">lib-libz</a> are the canonical examples, and the generated CLI SDKs (<a href="https://github.com/handl-lang/lib-gh" target="_blank" rel="noreferrer">lib-gh</a>, <a href="https://github.com/handl-lang/lib-cli-gen" target="_blank" rel="noreferrer">lib-cli-gen</a>) follow the same spec-plus-gate pattern.</p><h2 id="codemods" tabindex="-1">Codemods <a class="header-anchor" href="#codemods" aria-label="Permalink to “Codemods”">​</a></h2><ul><li><a href="https://github.com/handl-lang/tool-codemod" target="_blank" rel="noreferrer">tool-codemod</a> — the declarative codemod engine&#39;s spec/model layer; rewrite rules as data, same philosophy as the transform engines. Packaged for <code>hnl</code> as the <code>ext-codemod</code> extension (see <a href="/docs/ecosystem/extensions.html">Extensions</a>).</li></ul><p>The design rule across the family: foreign surfaces become <em>typed Handl declarations</em> — specs are the source of truth, generated code is rebuilt, never hand-edited.</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};